import PasswordContext from "./password-context";
import React, { useState, useEffect } from "react";

const PasswordProvider = (props) => {
  const [items, setItem] = useState([]);
  //  const totalQuantity = items.reduce((acc, item) => acc + item.amount, 0);

  const [showForm, setShowForm] = useState(false);
  const [openProduct, setOpenProduct] = useState(false);
  const [totalQuantity, setTotalQuantity] = useState(0);

  useEffect(() => {
    setTotalQuantity(items.length);
  }, [items]);

  console.log(totalQuantity);

  const handleForm = () => {
    setShowForm(true);
  };

  const closeForm = () => {
    setShowForm(false);
  };

  const handleProduct = () => {
    setOpenProduct(true);
  };

  const itemHandler = (item) => {
    console.log(item);
    setItem((prevItem) => [...prevItem, item]);
  };

  const deleteItem = (id) => {
    const updatedItems = items.filter((item) => item.id !== id);
    setItem(updatedItems);
  };

  const editItems = (id) => {
    // first i have to remove that item from screen
    const updatedItems = items.filter((item) => item.id !== id);
    setItem(updatedItems);
    // then control and details of that item should get refileed automatically in userForm and modal get open
    const itemToEdit = items.find((item) => item.id === id);

    // Refill the control and details of the item in the UserForm
    const titleInput = document.getElementById("title");
    const passwordInput = document.getElementById("password");

    if (itemToEdit) {
      titleInput.value = itemToEdit.title;
      passwordInput.value = itemToEdit.password;
    }

    // Open the modal to edit the item
    handleForm();
  };

  const passwordContext = {
    item: items,
    showForm,
    addItem: itemHandler,
    totalQuantity,
    openProduct,
    handleForm,
    closeForm,
    handleProduct,
    removeItem: deleteItem,
    editItem: editItems,
  };

  return (
    <PasswordContext.Provider value={passwordContext}>
      {props.children}
    </PasswordContext.Provider>
  );
};
export default PasswordProvider;
